namespace docking.widgets.table;








public abstract class IconButtonTableCellEditor<R> : AbstractCellEditor, TableCellEditor {
	protected static readonly string BLANK = "";
	protected JButton button = new JButton(BLANK);

	private Class<R> cls;

	protected R row;
	protected TableModel model;

	public IconButtonTableCellEditor(Class<R> cls, Icon icon) {
		this.cls = cls;
		button.setIcon(icon);
		button.addActionListener(this.doClicked);
	}

	/* @Override */
	public object getCellEditorValue() {
		return BLANK;
	}

	/* @Override */
	/* @SuppressWarnings("hiding") */
	public Component getTableCellEditorComponent(JTable table, object value, bool isSelected,
			int row, int column) {
		if (!(table is GTable gtable)) {
			return null;
		}
		GTableFilterPanel<object> filterPanel = gtable.getTableFilterPanel();
		if (filterPanel == null) {
			// There has to be some other way to get a "row object", no?
			return null;
		}
		object rowObj = filterPanel.getRowObject(row);
		if (!cls.isInstance(rowObj)) {
			return null;
		}
		this.row = cls.cast(rowObj);
		button.setToolTipText(value.toString());
		this.model = gtable.getUnwrappedTableModel();

		return button;
	}

	private void doClicked(ActionEvent e) {
		fireEditingStopped();
		clicked();
	}

	protected abstract void clicked();
}
